package com.rodrigosambade.uwbranging;
import android.app.*;import android.os.*;import android.Manifest;import android.content.pm.PackageManager;import android.widget.*;import androidx.core.uwb.*;import androidx.core.uwb.rxjava3.*;import io.reactivex.rxjava3.disposables.*;import java.util.*;
public class MainActivity extends Activity{TextView out;UwbManager manager;CompositeDisposable bag=new CompositeDisposable();@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,32,32,32);Button c=new Button(this);c.setText("Check UWB manager");c.setOnClickListener(v->check());l.addView(c);Button r=new Button(this);r.setText("Start demo ranging session");r.setOnClickListener(v->range());l.addView(r);out=new TextView(this);l.addView(out);setContentView(l);if(checkSelfPermission(Manifest.permission.UWB_RANGING)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.UWB_RANGING},1);}
void check(){try{if(manager==null)manager=UwbManager.createInstance(this);out.setText("UWB manager available. A real peer is still required for ranging.");}catch(Throwable t){out.setText("UWB unavailable: "+t.getClass().getSimpleName()+" — "+t.getMessage());}}
void range(){try{if(manager==null)manager=UwbManager.createInstance(this);bag.add(UwbManagerRx.controleeSessionScopeSingle(manager).flatMapObservable(scope->{UwbDevice peer=UwbDevice.createForAddress(new byte[]{0x01,0x02});RangingParameters p=new RangingParameters(RangingParameters.CONFIG_UNICAST_DS_TWR,7,0,null,null,null,Collections.singletonList(peer),RangingParameters.RANGING_UPDATE_RATE_AUTOMATIC,null,RangingParameters.RANGING_SLOT_DURATION_2_MILLIS,false);return UwbClientSessionScopeRx.rangingResultsObservable(scope,p);}).subscribe(x->runOnUiThread(()->out.setText("Ranging event: "+x.getClass().getSimpleName())),e->runOnUiThread(()->out.setText("Session requires compatible peer/config: "+e.getClass().getSimpleName()+" — "+e.getMessage()))));}catch(Throwable t){out.setText("Cannot start: "+t.getClass().getSimpleName()+" — "+t.getMessage());}}
@Override protected void onDestroy(){super.onDestroy();bag.dispose();}
}
